#include <stdlib.h>
#include <stdio.h>
#include <omp.h>

void prefix_sum(int* a, int index, size_t n, size_t block_size, int* flag)
{
    // Initialize flag array
    for (int i = 0; i < n; i++) {
        flag[i] = 0;
    }

    // Perform block-wise parallel prefix sum
    for (int i = index; i < n; i += block_size) {
        int start = i;
        int end = std::min(i + block_size, n);

        // Compute local prefix sum
        for (int j = start; j < end - 1; j++) {
            a[j] = a[j] + a[j + 1];
        }

        // Wait for previous block to complete
        if (start > 0 && !flag[start - 1]) {
            #pragma omp flush
            flag[start - 1] = 1;
        }

        // Adjust values based on previous block
        if (start > 0) {
            a[start - 1] += a[end - 1];
        }
    }
}

